module top_module(sda_i, s_axi_aclk, scndry_out, detect_stop_b_reg);input sda_i;
  input s_axi_aclk;
  output scndry_out;
  output detect_stop_b_reg;

  reg [2:0] sda_reg;
  wire sda_d1 = sda_reg[1];
  wire sda_d2 = sda_reg[2];

  reg [2:0] cnt;
  wire cnt_d1 = cnt[1];
  wire cnt_d2 = cnt[2];

  assign detect_stop_b_reg = (cnt_d2 & ~cnt_d1 & sda_d2 & sda_d1);

  always @(posedge s_axi_aclk) begin
    sda_reg <= {sda_i, sda_reg[2]};
    cnt <= {cnt[1:0], sda_d1 ^ sda_d2};
  end

  assign scndry_out = cnt_d2;

endmodule

