module security_alarm (
	input clk,
	input resetn,
	input arm,
	input trigger,
	output alarm);

	parameter DISARMED=0, ARMED=1, ALARM=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= DISARMED;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			DISARMED: next_state = arm ? ARMED : DISARMED;
			ARMED: next_state = trigger ? ALARM : ARMED;
			ALARM: next_state = DISARMED;
			default: next_state = DISARMED;
		endcase
	end

	assign alarm = (state == ALARM);
endmodule

