description:
Implement an 8-bit wide dual-port synchronous RAM module with separate read and write controls. The module allows concurrent read and write operations on two different addresses, AA and AB, based on the clock signals CLKA and CLKB, respectively. When CENA is asserted low, data from the memory at address AA is outputted to QA, whereas when CENB is asserted low, data input DB is written to memory at address AB. The address width is dynamically determined based on the specified word depth, ensuring efficient memory usage.
module top_module(

   QA,

   CLKA, CLKB, CENA, CENB, AA, AB, DB
   );

code:
module top_module(

   QA,

   CLKA, CLKB, CENA, CENB, AA, AB, DB
   );parameter       WORD_DEPTH = 8,
                DATA_WIDTH = 8;
localparam      ADDR_WIDTH = nextpow2(WORD_DEPTH);

input                           CLKA;
input                           CLKB;
input                           CENA;
input                           CENB;
input  [ADDR_WIDTH-1:0]         AA;
input  [ADDR_WIDTH-1:0]         AB;

output [DATA_WIDTH-1:0]         QA;
input  [DATA_WIDTH-1:0]         DB;


function integer nextpow2(input integer x);
      integer t;
      begin
	 t=x-1;
	 for(nextpow2=0; t>0; nextpow2=nextpow2+1)
	   t = t >> 1;
      end
endfunction 

  reg    [DATA_WIDTH-1:0]         memory[0:WORD_DEPTH-1];
  reg    [DATA_WIDTH-1:0]         QA;


  always @(posedge CLKB) begin
    if (!CENB)
      memory[AB] <= DB;
  end


  always @(posedge CLKA) begin
    if (!CENA)
      QA <= memory[AA];
  end

endmodule

