  reg signed [31:0] x_im_fp;
  reg signed [31:0] y_re_fp;
  reg signed [31:0] y_im_fp;
  reg signed [31:0] z_re_fp;
  reg signed [31:0] z_im_fp;

  always @ (posedge clk) begin
    if (!rst_n) begin
      x_re_fp <= 0;
      x_im_fp <= 0;
      y_re_fp <= 0;
      y_im_fp <= 0;
      z_re_fp <= 0;
      z_im_fp <= 0;
