      x_re_fp <= x_re << 16;
      x_im_fp <= x_im << 16;
      y_re_fp <= y_re << 16;
      y_im_fp <= y_im << 16;
      z_re_fp <= (x_re_fp * y_re_fp - x_im_fp * y_im_fp) >> 16;
      z_im_fp <= (x_re_fp * y_im_fp + x_im_fp * y_re_fp) >> 16;
    end
  end

  assign z_re = z_re_fp[31:16];
  assign z_im = z_im_fp[31:16];

