module fsm_module (
        input clk,
        input reset,
        input signal,
        output reg out);parameter A=0, B=1, C=2, D=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= A;
		else state <= next;

	always_comb begin
		case (state)
			A: next = signal ? B : A;
			B: next = signal ? C : B;
			C: next = signal ? D : C;
			D: next = signal ? A : D;
			default: next = 'x;
		endcase
	end

	assign out = (state == B) || (state == D);

endmodule

