module gray_code_counter(
	input clk,
	input reset_n,
	output reg [9:0] q);wire [9:0] next_q;
assign next_q = (q >> 1) ^ q;

always @(posedge clk or negedge reset_n)
	if (!reset_n)
		q <= 10'b0;
	else
		q <= next_q;

endmodule

