    or u_or2(or2_out, or1_out, and3_out);
    or u_or3(or3_out, or2_out, and4_out);

    xor u_xor1(xor1_out, A, B);
    xor u_xor2(xor2_out, C, D);

    or u_or4(Y, xor1_out, xor2_out, or3_out);

