module top_module(
  input         data_in,
  input         clk_in,
  input         clk_out,
  input         reset,
  output reg    data_out
);reg [1:0] sync_data;
  always @(posedge clk_in) begin
    sync_data <= {data_in, sync_data[0]};
  end

  always @(posedge clk_out) begin
    if (reset) begin
      sync_data <= 2'b0;
      data_out <= 1'b0;
    end else begin
      data_out <= sync_data[1];
    end
  end

endmodule

