module top_module(
    input areset,
    input inclk0,
    output reg c0,
    output reg locked
);parameter MULT = 8;
reg [31:0] count;
reg [31:0] phase_accumulator;
wire [31:0] phase_increment;

assign phase_increment = (inclk0 * MULT) / 100_000_000;

always @(posedge inclk0, negedge areset) begin
    if (areset == 0) begin
        phase_accumulator <= 0;
        count <= 0;
        c0 <= 0;
        locked <= 1;
    end else begin
        phase_accumulator <= phase_accumulator + phase_increment;
        if (phase_accumulator >= 2**32) begin
            phase_accumulator <= phase_accumulator - 2**32;
            count <= count + 1;
        end
        if (count >= MULT/2) begin
            count <= 0;
            c0 <= ~c0;
        end
        if (locked == 1 && count == 0) begin
            locked <= 0;
        end
    end
end

endmodule

