module top_module(
  input clk, // Added clock input
  input [n-1:0] in,
  input [L-1:0] coef,
  output reg [m-1:0] out // Changed output to 'reg' type
);parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter L = 5; // number of coefficients

reg [n-1:0] input_delay [0:L-1];

integer i, j;

always @ (posedge clk) begin
  // Shift input delay registers
  for (i = L-1; i > 0; i = i - 1) begin
    input_delay[i] <= input_delay[i-1];
  end

  // Add new input to delay register
  input_delay[0] <= in;

  // Compute output
  for (j = 0; j < m; j = j + 1) begin
    out[j] = 0; // Using non-blocking assignment for reg output
    for (i = 0; i < L; i = i + 1) begin
      out[j] = out[j] + input_delay[i][j] * coef[i];
    end
  end
end

endmodule

