module top_module(
  input clk,
  input reset,
  input [7:0] data,
  output reg match
);reg [3:0] state;
  reg [3:0] next_state;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
      match <= 1'b0;
    end else begin
      state <= next_state;
      match <= (state == 4'b0100);
    end
  end

  always @ (state or data) begin
    case (state)
      4'b0000: next_state = (data == 4'b1010) ? 4'b0100 : 4'b0001;
      4'b0001: next_state = (data[6:3] == 4'b1010) ? 4'b0100 : 4'b0010;
      4'b0010: next_state = (data[5:2] == 4'b1010) ? 4'b0100 : 4'b0011;
      4'b0011: next_state = (data[4:1] == 4'b1010) ? 4'b0100 : 4'b0001;
      4'b0100: next_state = 4'b0001;
      default: next_state = 4'b0000;
    endcase
  end

endmodule

