module top_module(
    input clk,          // Added clk as an input
    input [1:0] in,
    output reg [15:0] out
);reg [15:0] stage1_out;
reg [15:0] stage2_out;
reg [15:0] stage3_out;

always @ (posedge clk) begin
    stage1_out <= 16'b0; // Clear stage1_out
    stage1_out[in] <= 1'b1; // Set the bit according to input
end

always @ (posedge clk) begin
    stage2_out <= stage1_out;
end

always @ (posedge clk) begin
    stage3_out <= stage2_out;
end

assign out = stage3_out;

endmodule

