module top_module(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  input CLK,
  input RST,
  output [3:0] SUM,
  output COUT
);reg [3:0] SUM_reg;
  reg COUT_reg;

  always @(posedge CLK, negedge RST) begin
    if (~RST) begin
      SUM_reg <= 4'b0;
      COUT_reg <= 1'b0;
    end else begin
      SUM_reg <= A + B + CIN;
      COUT_reg <= (A[3] & B[3]) | (A[3] & CIN) | (B[3] & CIN);
    end
  end

  assign SUM = SUM_reg;
  assign COUT = COUT_reg;

endmodule

module top_module(
    input clk,
    input [31:0]div,

    input scl_en, 
    output scl_o,
    output scl_beat
    );reg [31:0]cnt = 0;
    always@(posedge clk)begin
        if(cnt == div-1)begin
            cnt <= 0;
        end
        else begin
            cnt <= cnt + 1;
        end        
    end
    reg scl_reg=1'b1;
    always@(posedge clk)begin
        if(cnt == 0) scl_reg <= 1'b1;
        else if(cnt == {1'b0,div[31:1]}-1) scl_reg <= 1'b0;
        else scl_reg <= scl_reg;
    end

    reg scl_o_reg=1'b1;
    always@(posedge clk)begin
        if(cnt == 0) scl_o_reg <= 1'b1;
        else if(cnt == {1'b0,div[31:1]}-1 && scl_en) scl_o_reg <= 1'b0;
        else scl_o_reg <= scl_o_reg;
    end

    assign scl_o = scl_o_reg;
    assign scl_beat = scl_reg;


endmodule

module top_module(
    input [3:0] a,
    input [3:0] b,
    output reg gt,
    output reg lt,
    output reg eq,
    input enable,
    input [1:0] select,
    input invert,
    output reg [7:0] out
);// 4-bit magnitude comparator module
    assign gt = (a > b);
    assign lt = (a < b);
    assign eq = (a == b);

    // 3-to-8 decoder module
    reg [7:0] decoder_out;
    always @ (enable or select) begin
        case (select)
            2'b00: decoder_out = 8'b00000001;
            2'b01: decoder_out = 8'b00000010;
            2'b10: decoder_out = 8'b00000100;
            2'b11: decoder_out = 8'b00001000;
        endcase
        if (invert) decoder_out = ~decoder_out;
    end

    // Functional module
    always @ (gt or lt or eq or decoder_out) begin
        out = (gt & decoder_out) | (lt & ~decoder_out) | (eq & enable);
    end

endmodule

