description:
Design a clock delay circuit that produces an output clock signal (clk_out) with a specified delay based on a counter. The module takes an input clock signal (clk_in) and a delay parameter, enabling the output clock to remain high until the specified delay count is reached, at which point it becomes low. The output will remain low until the next positive edge of clk_in is detected, at which time the counter resets, allowing for repeated cycles of delayed clock output.
module top_module(
    input clk_in,
    output reg clk_out,
    input delay
);

code:
module top_module(
    input clk_in,
    output reg clk_out,
    input delay
);reg [31:0] counter;
reg delay_reached;

always @(posedge clk_in) begin
    if(delay_reached) begin
        counter <= 0;
        delay_reached <= 0;
        clk_out <= 1;
    end
    else if(counter == delay) begin
        delay_reached <= 1;
        clk_out <= 0;
    end
    else begin
        counter <= counter + 1;
        clk_out <= 1;
    end
end

endmodule

