    input axis_tlast,
    input axis_tvalid,
    output axis_tready,

    input native_full,
    output [8:0]native_din, 
    output native_wr_en
);reg [1:0] counter = 0;
reg zero_padding = 0;

always @(posedge clk or posedge rst) begin
    if (rst) counter <= 0;
    else if (native_wr_en)
        counter <= counter + 1;
    if (rst) zero_padding <= 0;
    else if (counter == 3) zero_padding <= 0;
    else if (axis_tlast) zero_padding <= 1;
end
