    reg CLK;
    reg UDP_IN;
    reg VPWR;
    wire UDP_OUT;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .CLK(CLK),
        .UDP_IN(UDP_IN),
        .VPWR(VPWR),
        .UDP_OUT(UDP_OUT)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            UDP_IN = 0;
            VPWR = 0;

            @(posedge CLK);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            reset_dut();
            $display("Testcase 001: VPWR=1, UDP_IN=0 -> Expected UDP_OUT=1");
            VPWR = 1;
            UDP_IN = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            reset_dut();
            $display("Testcase 002: VPWR=1, UDP_IN=1 -> Expected UDP_OUT=0");
            VPWR = 1;
            UDP_IN = 1;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            reset_dut();
            $display("Testcase 003: VPWR=0, UDP_IN=0 -> Expected UDP_OUT=0");
            VPWR = 0;
            UDP_IN = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
