        begin
            test_num = 4;
            reset_dut();
            $display("Testcase 004: VPWR=0, UDP_IN=1 -> Expected UDP_OUT=0");
            VPWR = 0;
            UDP_IN = 1;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            reset_dut();
            $display("Testcase 005: Input changes mid-cycle should not affect output until next edge");
            VPWR = 1;
            UDP_IN = 0;
            @(posedge CLK);
            #2;
            VPWR = 0;
            UDP_IN = 1;
            #1;

            if (UDP_OUT === 1'b1) begin
                @(posedge CLK);
                #2;
                #1;

                check_outputs(1'b0);
            end else begin
                $display("FAIL: Output changed asynchronously");
                fail_count = fail_count + 1;
