module top_module(
    input A,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg X
);reg [3:0] delay_counter;

    always @ (posedge VPWR or negedge VGND) begin
        if (A) begin
            delay_counter <= delay_counter + 1;
            if (delay_counter == 4) begin
                X <= 1;
            end
        end else begin
            delay_counter <= 0;
            X <= 0;
        end
    end

endmodule

module johnson_counter (
    input clk,
    input reset,
    output [4:0] q );reg [4:0] count_reg;

always @(posedge clk) begin
    if (reset)
        count_reg <= 5'b00000;
    else
        count_reg <= {count_reg[3:0], ~count_reg[4]};
end

assign q = count_reg;

endmodule

