module top_module(
  input clock,
  input reset,
  input wEn, 
  input [31:0] write_data,
  input [4:0] read_sel1,
  input [4:0] read_sel2,
  input [4:0] write_sel,
  output [31:0] read_data1,
  output [31:0] read_data2
);reg   [31:0] reg_file[0:31];



assign read_data1 = reg_file[read_sel1];
assign read_data2 = reg_file[read_sel2];

always@(posedge clock) begin

	if(reset) begin
		reg_file[0] <= 32'd0;
	end else if(wEn && write_sel == 5'b00000) begin
		reg_file[write_sel] <= 32'd0;
	end else if (wEn) begin
		reg_file[write_sel] <= write_data;
	end else begin
		reg_file[write_sel] <= reg_file[write_sel];
	end

end

endmodule

module down_counter (CLK, RST, Q);
input CLK, RST;
output reg [3:0] Q;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Q <= 4'b1111;
    end else begin
        Q <= Q - 1;
    end
end

endmodule

